tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import { spawnSync } from 'node:child_process';
const env = {...process.env, npm_config_offline:'true', npm_config_update_notifier:'false', npm_config_logs_max:'0'};
for (const args of [['--silent','start','--','5'],['--silent','run','locate'],['--silent','run','drain']]) {
  const result = spawnSync('npm', args, {env, encoding:'utf8', timeout:5000});
  console.log(JSON.stringify({command:['npm',...args].join(' '), exit:result.status, signal:result.signal, stdout:result.stdout, stderr:result.stderr, error:result.error?.message}));
}
NODE"

